 "content": "def transform(grid):
    """Shift the foreground shape one row downward and mark its old top row."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    marker_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    marker_color = grid[marker_rows[0]][0] if marker_rows else None
    shape = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row)
             if v != bg and v != marker_color]
    if not shape:
        return [row[:] for row in grid]
    top = min(r for r, _, _ in shape)
    out = [row[:] for row in grid]
    out[top] = [8] * w
    for r, c, v in shape:
        nr = r + 1
        if nr < h:
            out[nr][c] = v
    return out
