              if v != bg and v != div_color]
    if not pixels:
        return [row[:] for row in grid]
    rows = [r for r, _, _ in pixels]
    top, bottom = min(rows), max(rows)
    # Slide the colored figure toward the divider until it touches it.
    if bottom < divider:
        shift = divider - 1 - bottom
        stripe_row = top + shift - 1
